message.content:
{
  "title": "Clockwork Rescue Over Glass",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team arrives at the ruined city gates.",
      "visual_description": "Crumbled stone gates loom under a bruised sky; torn royal banners flutter from bent poles; the glass diver adjusts his helmet while Mara studies a half-burned map.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's single eye flickers as it speaks; beyond, a crooked tower oozes phosphorescent green light; Mara marks the danger on her map.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the outer ward.",
      "visual_description": "The clockwork fox scurries over broken cobbles, its blue eyes scanning; torn banners and shattered windows reflect in the glass diver's helmet.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The team finds the Sleeping Tax Collector dozing at a checkpoint.",
      "visual_description": "A makeshift desk blocks the path; the tax collector snores with a ledger as pillow, stamped papers stuck to his sleeves; Mara sighs in frustration.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "Glass Diver peers through a broken window to see a route.",
      "visual_description": "The glass diver presses his helmet against a shattered pane; beyond, a courtyard filled with armored patrols marches in lockstep; his reflection splits the scene.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Oracle Lamp reveals a secret passage behind a magic door.",
      "visual_description": "The lamp's flame illuminates a shimmering door etched with shifting runes; it whispers the counter-command; Mara notes the pattern.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Tin Fox triggers a hidden alarm near the tower base.",
      "visual_description": "The metal fox steps on a pressure plate; a bell clangs inside the tower; armored patrols pivot toward the sound; the fox freezes mid-step.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The team hides behind old royal banners as patrols march past.",
      "visual_description": "Frayed banners embroidered with faded crests hang from a collapsed awning; the team presses flat as armored boots echo on stone; the lamp dims its glow.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Sleeping Tax Collector stirs but offers no help.",
      "visual_description": "He half-opens one eye, mumbles about tolls, then rolls over; a stamped paper flutters onto Mara's boot; she picks it up — it's a map fragment.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Mara deciphers the map fragment near a cracked fountain.",
      "visual_description": "She spreads the paper on dry stone; the ink-stained map shows a path through a collapsed cistern; glass diver holds his lamp for light.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Tin Fox finds a rusted key in a cistern drain.",
      "visual_description": "The clockwork fox noses through murky water; its jaw clamps on a iron key; it trots back, dripping, and drops the key at Mara's feet.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Oracle Lamp warns of a false floor ahead.",
      "visual_description": "The lamp's eye narrows; it reveals a seam in the flagstones; glass diver taps ahead with his boot and the floor gives way to a dark pit.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Glass Diver swims through a mirror into a sealed treasury.",
      "visual_description": "He presses his helmet against a tall mirror, steps through like diving into water; on the other side, a dusty chamber holds the bridge lever.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Mara marks the exit route while the team regroups.",
      "visual_description": "In a collapsed chapel, she traces the final path on her map; tin fox sits at watch; oracle lamp glows steadily; glass diver returns with the lever.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Sleeping Tax Collector is carried to safety despite his protests.",
      "visual_description": "He grumbles as glass diver hoists him over one shoulder; his ledger trails behind; Mara leads the way through a narrow alley.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The team activates the bridge mechanism from the tower base.",
      "visual_description": "Glass diver fits the key into a rusty console; gears groan; beyond, a drawbridge begins to lower across a chasm; armored patrols turn and charge.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The final sprint across the bridge under pursuit.",
      "visual_description": "The team runs across mossy planks; behind them, armored patrols pour from the gatehouse; oracle lamp flickers wildly; tin fox's legs whir at top speed.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them, sealing the escape.",
      "visual_description": "On the far side, the team watches as the bridge breaks free and falls into the mist; the ruined city fades; oracle lamp dims to a steady glow; Mara folds her map.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

